package app.space.notes.domain;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ContentControlsTest {
 private AutoListContinuation.Edit enter(String text){return AutoListContinuation.afterEnter(text,text.length()-1);}
 @Test public void backspaceRemovesPrefixAndPreservesFollowingText(){String source="First\n12. After";AutoListContinuation.Edit edit=AutoListContinuation.beforeBackspace(source,10);assertEquals(6,edit.start);assertEquals(10,edit.end);assertEquals("First\nAfter",source.substring(0,edit.start)+source.substring(edit.end));assertNull(AutoListContinuation.beforeBackspace(source,11));assertNull(AutoListContinuation.beforeBackspace("1. Thing",2));}
 @Test public void firstTypedNumberContinues(){AutoListContinuation.Edit change=enter("1. First\n");assertEquals(9,change.start);assertEquals(change.start,change.end);assertEquals("2. ",change.replacement);}
 @Test public void startsAtTypedNumberAndContinuesAfterExistingParagraph(){assertEquals("43. ",enter("Before\n42. Answer\n").replacement);}
 @Test public void emptyNumberedEntryLeavesList(){AutoListContinuation.Edit change=enter("First\n2. \n");assertEquals(6,change.start);assertEquals(10,change.end);assertEquals("",change.replacement);}
 @Test public void onlyLiteralPrefixAtStartOfParagraphIsRecognized(){for(String line:Arrays.asList(" 1. indented\n","prefix 1. text\n","0. text\n","01. text\n","1.text\n","- point\n","normal\n"))assertNull(line,enter(line));}
 @Test public void removedPrefixDoesNotReturnOnEnter(){assertNull(enter("First\ntext\n"));assertNull(enter("1.\n"));}
 @Test public void overflowAndInvalidNewlineAreNotGuessed(){assertNull(enter("9999. Final\n"));assertNull(AutoListContinuation.afterEnter("1. Text",7));assertNull(AutoListContinuation.afterEnter("1. Text",-1));}
 @Test public void splitAtCaretAddsNumberWithoutDeletingSuffix(){String source="1. Before\nAfter";AutoListContinuation.Edit change=AutoListContinuation.afterEnter(source,9);assertEquals("1. Before\n2. After",source.substring(0,change.start)+change.replacement+source.substring(change.end));}
 @Test public void checklistCopyPreservesRichRowsAndGetsIndependentIdentities(){DocumentContent.Block source=DocumentContent.Block.checklist("list","Shopping",Arrays.asList(new Note.Item("row","Milk",true,2,Arrays.asList(new Note.Mark("bold",0,4)))),true),copy=ContentCopies.copy(source);assertNotEquals(source.id,copy.id);assertNotEquals(source.items.get(0).id,copy.items.get(0).id);assertEquals(source.name,copy.name);assertTrue(copy.hideChecked);assertTrue(copy.items.get(0).checked);assertEquals(2,copy.items.get(0).depth);assertEquals("Milk",copy.items.get(0).text);assertEquals("bold=;",TypingStyle.capture(new RichText(copy.items.get(0).text,copy.items.get(0).marks),0,4).encode());assertEquals(2,new DocumentContent(Arrays.asList(source,copy)).blocks.size());}
 @Test public void visualCopyGetsIndependentImageIdentityWithoutFlatteningOrDuplicatingPayload(){NoteImage image=new NoteImage(UUID.randomUUID().toString(),"Ink","image/png",1,1,"iVBORw0KGgo=");for(DocumentContent.Kind kind:Arrays.asList(DocumentContent.Kind.IMAGE,DocumentContent.Kind.DRAWING)){DocumentContent.Block source=DocumentContent.Block.visual("visual","Drawing01",kind,image),copy=ContentCopies.copy(source);assertNotEquals(source.image.id,copy.image.id);assertEquals(source.image.data,copy.image.data);assertEquals(source.image.name,copy.image.name);assertEquals(source.kind,copy.kind);assertEquals(2,new DocumentContent(Arrays.asList(source,copy)).blocks.size());}}
 @Test public void tableCopyPreservesHeaderWidthCellsAndRichMarks(){TextTable table=TextTable.empty(2,2).withHeader(true).withColumnWidth(220).withRichCell(1,1,new RichText("Keep",Arrays.asList(new Note.Mark("italic",0,4))));DocumentContent.Block copy=ContentCopies.copy(DocumentContent.Block.table("table","Table01",table));assertSame(table,copy.table);assertTrue(copy.table.hasHeader);assertEquals(220,copy.table.columnWidth);assertEquals("italic=;",TypingStyle.capture(copy.table.cells.get(1).get(1),0,4).encode());}
 @Test public void diagramCopyKeepsEditableModelAndSourceName(){Diagram diagram=Diagram.empty();DocumentContent.Block source=DocumentContent.Block.diagram("diagram","Travel",diagram),copy=ContentCopies.copy(source);assertNotEquals(source.id,copy.id);assertEquals("Travel",copy.name);assertSame(diagram,copy.diagram);}
 @Test public void caretInsertionPreservesTextStylesAndDoesNotUseSelectionConversion(){DocumentContent source=new DocumentContent(Arrays.asList(DocumentContent.Block.text("writing",new RichText("BeforeAfter",Arrays.asList(new Note.Mark("bold",0,11))))));DocumentContent after=source.insertAtText("writing",6,DocumentContent.Block.checklist("list","Checklist01",Arrays.asList(new Note.Item("row","",false,0)),false));assertEquals(3,after.blocks.size());assertEquals("Before",after.blocks.get(0).text.text);assertEquals("After",after.blocks.get(2).text.text);assertEquals("bold=;",TypingStyle.capture(after.blocks.get(0).text,0,6).encode());assertEquals("BeforeAfter",source.block("writing").text.text);}
 private String apply(String source,int newline){AutoListContinuation.Edit edit=AutoListContinuation.afterEnter(source,newline);StringBuilder text=new StringBuilder(source);for(int i=edit.following.size()-1;i>=0;i--){AutoListContinuation.Edit next=edit.following.get(i);text.replace(next.start,next.end,next.replacement);}text.replace(edit.start,edit.end,edit.replacement);return text.toString();}
 @Test public void insertionRenumbersFollowingLiteralItems(){assertEquals("1. First\n2. \n3. Second\n4. Third",apply("1. First\n\n2. Second\n3. Third",8));}
 @Test public void renumberingStopsAtUnnumberedParagraph(){assertEquals("8. First\n9. suffix\n10. Next\nordinary\n1. Separate",apply("8. First\nsuffix\n9. Next\nordinary\n1. Separate",8));}
 @Test public void digitWidthChangesUseOriginalOffsets(){assertEquals("8. First\n9. \n10. Second\n11. Third",apply("8. First\n\n9. Second\n10. Third",8));}
}
